            Workers missing from the mapping have no cap. Jobs that cannot be
            assigned because all workers have reached capacity are omitted.

    Returns:
        List of {"job": str, "worker": str} dicts.

    Raises:
        TypeError: If arguments are of the wrong type.
        ValueError: If no workers are enabled, or if worker/job entries are
            malformed, or if capacity values are not positive integers.
    """
    # --- validate workers ---
    if not isinstance(workers, list):
        raise TypeError(
            f"'workers' must be a list, got {type(workers).__name__!r}"
        )
    for i, w in enumerate(workers):
        if not isinstance(w, dict):
            raise TypeError(
                f"Each worker must be a dict; workers[{i}] is "
                f"{type(w).__name__!r}"
            )
        if "name" not in w:
            raise ValueError(
                f"Worker at index {i} is missing required key 'name'"
            )
        if not isinstance(w["name"], str):
            raise ValueError(
                f"Worker 'name' must be a str; workers[{i}]['name'] is "
                f"{type(w['name']).__name__!r}"
            )
        if not w["name"]:
            raise ValueError(
                f"Worker 'name' must be a non-empty string; "
                f"workers[{i}]['name'] is empty"
            )
        enabled = w.get("enabled", True)
        if not isinstance(enabled, bool):
            raise TypeError(
                f"Worker 'enabled' must be a bool; workers[{i}]['enabled'] is "
                f"{type(enabled).__name__!r}"
            )

    # --- validate jobs ---
    if not isinstance(jobs, list):
        raise TypeError(
            f"'jobs' must be a list, got {type(jobs).__name__!r}"
        )
    for i, job in enumerate(jobs):
        if not isinstance(job, str):
            raise TypeError(
                f"Each job must be a str; jobs[{i}] is "
