                f"Job identifiers must be non-empty strings; "
                f"jobs[{i}] is empty"
            )

    # --- validate capacities ---
    if capacities is not None:
        if not isinstance(capacities, dict):
            raise TypeError(
                f"'capacities' must be a dict or None, "
                f"got {type(capacities).__name__!r}"
            )
        for worker_name, cap in capacities.items():
            if not isinstance(worker_name, str):
                raise TypeError(
                    f"Capacity keys must be str; got "
                    f"{type(worker_name).__name__!r}"
                )
            if not isinstance(cap, int) or isinstance(cap, bool):
                raise TypeError(
                    f"Capacity values must be int; capacities[{worker_name!r}] "
                    f"is {type(cap).__name__!r}"
                )
            if cap < 0:
                raise ValueError(
                    f"Capacity values must be non-negative; "
                    f"capacities[{worker_name!r}] is {cap}"
                )

    # --- core logic ---
